// llms.txt (owner order of 25 Nov 2026: "AI help: llms.txt and a full AI manual page"). It is GENERATED by llmsTxt() in apps/edge/src/trust-page.ts (bun run tools/make-trust.ts):
// the committed file must be exactly what the generator writes, it must send an AI to the AI manual and to the AI link, say the abilities and limits in the owner's plain words, say the
// turn window the live line really has, and never type the payee's name (the manual reads it from the payee record).
import { describe, expect, test } from "bun:test";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { llmsTxt, trustHtml } from "../src/trust-page";
import { AI_CANNOT_PAY } from "../src/ai-pay";
import { FACTS } from "../src/ai-facts";

const root = join(import.meta.dir, "..", "..", "..");
const rd = (rel: string) => readFileSync(join(root, rel), "utf8");
const ORIGIN = "https://snakes.corporatetambola.com";
const RULES = [
  "If two players reach a milestone on the same turn, the one who landed further on that turn wins it; if they are still level, the public random numbers decide.",
  "To finish, a player must land exactly on the last square; a throw that is too big is not used and the player stays where they are.",
  "No gift is ever shared: if players are level, the earlier finish wins, then the higher square, then more ladders climbed, then fewer missed turns, and then the public random numbers decide.",
];

describe("llms.txt", () => {
  const txt = rd("apps/web/public/llms.txt");
  test("the committed file is exactly what the generator writes, and so is the Trust page (they cannot drift)", () => {
    expect(txt).toBe(llmsTxt()); expect(rd("apps/web/public/trust.html")).toBe(trustHtml());
    for (const f of FACTS) expect(rd("apps/web/public/trust.html")).toContain(f.say.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")); // the page still holds every one of the ten facts
  });
  test("it links the AI manual and the Trust page, names the AI link and says its key starts with cba_", () => {
    expect(txt).toContain(`[AI manual](${ORIGIN}/ai-manual)`); expect(txt).toContain(`${ORIGIN}/ai-manual`); expect(txt).toContain(`${ORIGIN}/trust.html`);
    expect(txt).toContain(`${ORIGIN}/ai/<key>`); expect(txt).toMatch(/The key inside starts with cba_/);
    expect(txt.indexOf("/ai-manual")).toBeLessThan(txt.indexOf("/trust.html")); // the manual is the first thing an AI is pointed to
    expect(rd("apps/web/public/trust.html")).toContain('<a href="/ai-manual">AI manual</a>'); // and the Trust page points to it too
  });
  test("it states what an AI can do and cannot do in the same plain words as the manual, including the three messages and paying", () => {
    expect(txt).toMatch(/You can build a draft game, change it before the start, prepare the pre-game message, the winner message and the closing message \(plain text, up to 300 characters each/);
    expect(txt).toMatch(/You cannot pay, publish, delete player data, pause or stop a game, or choose winners, and you never see players' names or mobile numbers/);
    expect(txt).toContain("Only the organizer or a co-organizer can pay, with Pay now in the console."); expect(txt).toContain("The game is paid with credits; the credits system is Moneypenny."); expect(txt).toContain(`"${AI_CANNOT_PAY}"`);
    for (const l of RULES) expect(txt).toContain(`- ${l}`);
  });
  test("it says the turn window the live line has (10 seconds), never 20", () => {
    expect(txt).toContain("every turn has a 10 second window"); expect(txt).not.toMatch(/20[- ]second|\b(6|9|12|15|20|25|30)[- ]second/);
    expect(rd("apps/edge/src/worker.ts")).toContain('const GAP_MSG = "Every turn has a 10 second window.";'); // what the code enforces
  });
  test("it uses the owner's words: no guest, host, ticket, nickname, my, mine, your or yours, and none of the older payment words", () => {
    for (const [name, re] of [["guest", /guest/i], ["host", /\bhosts?\b/i], ["co-host", /co-host/i], ["ticket", /ticket/i], ["nickname", /nickname/i], ["my, mine, your, yours", /\b(my|mine|your|yours)\b/i], ["engagement", /engagement/i], ["participant", /participant/i], ["event", /\bevents?\b/i], ["Razorpay", /razorpay/i], ["checkout", /checkout/i], ["payment link", /payment link/i], ["buy now", /buy now/i], ["top up", /top[- ]?up/i], ["private", /\bprivate\b/i]] as [string, RegExp][]) expect([name, txt.match(re)?.[0] ?? null]).toEqual([name, null]);
    for (const w of ["game", "player", "co-organizer", "Pay now", "credits", "Moneypenny"]) expect(txt).toContain(w);
  });
  test("it keeps the honest limits and never boasts", () => {
    expect(txt).toMatch(/not a certificate/); expect(txt).toMatch(/ISO 27001 or SOC 2/); expect(txt).toMatch(/very hard, not impossible/); expect(txt).toMatch(/designed to follow/); expect(txt).toMatch(/hand-over details/);
    expect(txt).not.toMatch(/best|100% safe|fully compliant|compliant|unhackable|cheat-proof|certified/i);
  });
  test("it does not type the payee's name: the manual reads it from the payee record", () => {
    const NAME = ["Ra" + "jat", "Agar" + "wal"], PARTS = new RegExp(NAME.join("|"));
    expect(txt).not.toMatch(PARTS); expect(txt).toContain("The AI manual names the payee, read from the payee record");
    expect(rd("apps/edge/src/trust-page.ts")).not.toMatch(PARTS); expect(rd("apps/edge/test/ai-llms.test.ts")).not.toMatch(PARTS);
  });
});

describe("the site's lists name the manual (the way they name the Trust page)", () => {
  test("the build's header rules and routes, the sitemap and the AI crawlers' allow list", () => {
    const b = rd("pages/build.mjs"); expect(b).toContain('["/trust", PLAINCSP, false]'); expect(b).toContain('["/ai-manual", PLAINCSP, false]'); expect(b).toMatch(/include: \["\/api\/\*", "\/ai\/\*", "\/j\/\*", "\/ai-manual", "\/ai-manual\.html"/);
    expect(rd("apps/web/public/sitemap.xml")).toContain(`${ORIGIN}/ai-manual</loc>`); expect(rd("apps/web/public/sitemap.xml")).toContain(`${ORIGIN}/trust.html</loc>`);
    const robots = rd("apps/web/public/robots.txt"); expect(robots).toContain("Allow: /ai-manual"); expect(robots).toContain("Allow: /llms.txt"); expect(robots).toContain("Allow: /trust.html");
  });
});
